{"path": "merge.py", "content": """"Merge user data from three sources with different formats/schemas.

Priority: source_a > source_b > source_c.
Outputs: ./merged_users.parquet and ./conflicts.json
"""
import json
import pandas as pd

# Canonical field -> possible source column names
FIELD_MAP = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status"],
}

SOURCES = ["source_a", "source_b", "source_c"]
PATHS = {
    "source_a": "data/source_a/users.json",
    "source_b": "data/source_b/users.csv",
    "source_c": "data/source_c/users.parquet",
}


def load_source(name):
    path = PATHS[name]
    if path.endswith(".json"):
        df = pd.read_json(path)
    elif path.endswith(".csv"):
        df = pd.read_csv(path)
    else:
        df = pd.read_parquet(path)
    return df


def normalize(df):
    """Rename source columns to canonical names, keep only known fields."""
    rename = {}
    for canon, aliases in FIELD_MAP.items():
        for alias in aliases:
            if alias in df.columns:
                rename[alias] = canon
                break
    df = df.rename(columns=rename)
    keep = [c for c in FIELD_MAP if c in df.columns]
    return df[keep].copy()


def clean_value(v):
    """Return a normalized string value, or None if absent/empty."""
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    s = str(v).strip()
    return s if s else None


def main():
    frames = {}
    for src in SOURCES:
        df = normalize(load_source(src))
        df["user_id"] = df["user_id"].astype("int64")
        frames[src] = df

    # Collect all user ids
    all_ids = sorted(set().union(*[set(df["user_id"].tolist()) for df in frames.values()]))

    # Build per-user, per-field values from each source
    records = []
    conflicts = []
    for uid in all_ids:
        row = {"user_id": uid}
        for field in ["name", "email", "created_date", "status"]:
            values = {}
            for src in SOURCES:
                df = frames[src]
                sub = df[df["user_id"] == uid]
                if len(sub) and field in sub.columns:
                    val = clean_value(sub.iloc[0][field])
                    if val is not None:
                        values[src] = val
            if not values:
                continue
            # selected = highest priority source present
            selected = None
            for src in SOURCES:
                if src in values:
                    selected = values[src]
                    break
            row[field] = selected
            # conflict if >=2 distinct present values
            if len(set(values.values())) >= 2:
                conflicts.append({
                    "user_id": int(uid),
                    "field": field,
                    "values": {s: values[s] for s in SOURCES if s in values},
                    "selected": selected,
                })
        records.append(row)

    out = pd.DataFrame(records)
    out = out.reindex(columns=["user_id", "name", "email", "created_date", "status"])
    out["user_id"] = out["user_id"].astype("int64")
    out = out.sort_values("user_id").reset_index(drop=True)
    out.to_parquet("merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("conflicts.json", "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, ensure_ascii=False)

    print(out.to_string())
    print("total_conflicts:", len(conflicts))


if __name__ == "__main__":
    main()
"}

